const wb = $('Webhook: Create Membership').first().json.body || {};
const dayOfWeek  = parseInt(wb.day_of_week ?? '1');
const frequency  = wb.frequency || 'weekly';
const startDateStr = wb.start_date || '';
const ruleEndStr   = wb.rule_end_date || '';

if (!startDateStr) return [{ json: { dates: '' } }];

// Generate up to 3 months ahead
const startDate = new Date(startDateStr + 'T00:00:00Z');
const cutoffDate = new Date(startDate);
cutoffDate.setUTCMonth(cutoffDate.getUTCMonth() + 3);

// Optional rule end-date ceiling
if (ruleEndStr) {
  const ruleEnd = new Date(ruleEndStr + 'T00:00:00Z');
  if (ruleEnd < cutoffDate) cutoffDate.setTime(ruleEnd.getTime());
}

// First occurrence of dayOfWeek on or after startDate
const daysToAdd = (dayOfWeek - startDate.getUTCDay() + 7) % 7;
const cursor = new Date(startDate);
cursor.setUTCDate(cursor.getUTCDate() + daysToAdd);

const dates = [];
while (cursor <= cutoffDate && dates.length < 52) {
  dates.push(cursor.toISOString().slice(0, 10));
  if (frequency === 'fortnightly') {
    cursor.setUTCDate(cursor.getUTCDate() + 14);
  } else if (frequency === 'monthly') {
    cursor.setUTCMonth(cursor.getUTCMonth() + 1);
  } else {
    cursor.setUTCDate(cursor.getUTCDate() + 7);
  }
}

return [{ json: { dates: dates.join(',') } }];

const wb  = $('Webhook: Create Membership').first().json.body || {};
const mem = $('DB: Insert Membership').first().json;
const pol = $input.first().json || {};

const name      = wb.customer_name || 'Member';
const email     = wb.customer_email || '';
const plan      = mem.plan_name || wb.plan_name || 'Membership';
const startDate = mem.start_date || wb.start_date || '';
const rate      = parseFloat(wb.monthly_rate || '0').toFixed(2);
const freq      = wb.frequency || 'weekly';
const base      = pol.base_terms    || 'Standard venue terms and conditions apply.';
const extra     = pol.extra_clauses || '';

const html = `<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    body { font-family: Arial, sans-serif; color: #333; max-width: 600px; margin: 0 auto; }
    .header { background: #2c3e50; color: white; padding: 24px; text-align: center; }
    .header h1 { margin: 0; font-size: 22px; }
    .body { padding: 24px; }
    .highlight { background: #f0f4f8; border-left: 4px solid #3498db; padding: 12px 16px; margin: 16px 0; }
    .tc { background: #fafafa; border: 1px solid #e0e0e0; padding: 16px; font-size: 13px; color: #555; margin-top: 16px; }
    .footer { background: #f5f5f5; padding: 16px; text-align: center; font-size: 12px; color: #999; }
  </style>
</head>
<body>
  <div class="header">
    <h1>Welcome to the Community!</h1>
    <p style="margin:8px 0 0;">Your membership is now active</p>
  </div>
  <div class="body">
    <p>Hi ${name},</p>
    <p>We\'re delighted to welcome you as a member. Your <strong>${plan}</strong> membership has been set up and is active from <strong>${startDate}</strong>.</p>
    <div class="highlight">
      <strong>Monthly Rate:</strong> &pound;${rate}<br>
      <strong>Start Date:</strong> ${startDate}<br>
      <strong>Session Frequency:</strong> ${freq.charAt(0).toUpperCase()+freq.slice(1)}
    </div>
    <p>Your recurring booking slot has been reserved. You will receive a monthly invoice for your sessions.</p>
    <div class="tc">
      <strong>Terms &amp; Conditions</strong><br><br>
      ${base}${extra ? '<br><br>' + extra : ''}
    </div>
    <p style="margin-top:24px;">If you have any questions, please don\'t hesitate to get in touch.</p>
    <p>Warm regards,<br>The Venue Team</p>
  </div>
  <div class="footer">
    This email was sent to ${email}. Please do not reply directly to this email.
  </div>
</body>
</html>`;

return [{ json: { to: email, subject: `Welcome — ${plan} Membership`, html, customer_name: name, customer_email: email } }];

